function ContactList({ contacts }) {
  if (contacts.length === 0) return <p>No contacts yet.</p>;
  return (
    <ul>
      {contacts.map(contact => (
        <ContactCard key={contact.id} contact={contact} />
      ))}
    </ul>
  );
}

function Directory({ people }) {
  const [query, setQuery] = useState('');
  const visible = people.filter(p =>
    p.name.toLowerCase().includes(query.toLowerCase())
  );
  return (
    <>
      <SearchBox value={query} onChange={setQuery} />
      <ResultList people={visible} />
    </>
  );
}

function EmailField() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const invalid = touched && !/^\S+@\S+\.\S+$/.test(email);
  return (
    <label>
      Email
      <input value={email} onChange={e => setEmail(e.target.value)}
        onBlur={() => setTouched(true)} aria-invalid={invalid}
        aria-describedby="email-error" />
      {invalid && <span id="email-error">Enter a valid email</span>}
    </label>
  );
}

type Request<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; message: string };

function describe(req: Request<Habit[]>) {
  switch (req.status) {
    case 'success': return `${req.data.length} habits`;
    case 'error': return req.message;
    default: return 'Loading…';
  }
}
